INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Apex', 1, 2026, 'Baltasar Kormákur', 'A grieving woman pushing her limits on a solo adventure in the Australian wild is ensnared in a twisted game with a cunning killer who thinks she''s prey.', '1318447.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Super Mario Galaxy Movie', 2, 2026, 'Michael Jelenic', 'Having thwarted Bowser''s previous plot to marry Princess Peach, Mario and Luigi now face a fresh threat in Bowser Jr., who is determined to liberate his father from captivity and restore the family legacy. Alongside companions new and old, the brothers travel across the stars to stop the young heir''s crusade.', '1226863.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Your Heart Will Be Broken', 3, 2026, 'Mikhail Vaynberg', 'High school student Polina is saved from bullying at her new school and makes a deal with the main bully Bars: he must pretend to be her boyfriend and protect her, and she must do everything he says. During this game, the couple develops real feelings, but her family and classmates have reasons to separate the lovers.', '1523145.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Michael', 4, 2026, 'Antoine Fuqua', 'The story of Michael Jackson, one of the most influential artists the world has ever known, and his life beyond the music. His journey from the discovery of his extraordinary talent as the lead of the Jackson Five, to the visionary artist whose creative ambition fueled a relentless pursuit to become the biggest entertainer in the world, highlighting both his life off-stage and some of the most iconic performances from his early solo career.', '936075.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Send Help', 5, 2026, 'Sam Raimi', 'Two colleagues become stranded on a deserted island, the only survivors of a plane crash. On the island, they must overcome past grievances and work together to survive, but ultimately, it''s a battle of wills and wits to make it out alive.', '1198994.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('They Will Kill You', 1, 2026, 'Kirill Sokolov', 'A woman answers a help wanted ad to be a housekeeper in a mysterious New York City high-rise, unaware that she is entering a community that has seen a number of disappearances over the years and may be under the grip of a Satanic cult.', '1292695.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Avatar Aang: The Last Airbender', 6, 2026, 'Lauren Montgomery', 'Avatar Aang, the world''s last Airbender, learns of an ancient power that could save his culture from extinction. With the help of his friends, he embarks on a global quest to find it before it falls into the wrong hands and threatens to upend the peace they sacrificed everything to achieve.', '980431.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Hoppers', 7, 2026, 'Daniel Chong', 'Scientists have discovered how to ''hop'' human consciousness into lifelike robotic animals, allowing people to communicate with animals as animals. Animal lover Mabel seizes an opportunity to use the technology, uncovering mysteries within the animal world beyond anything she could have imagined.', '1327819.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Avatar: Fire and Ash', 8, 2025, 'James Cameron', 'In the wake of the devastating war against the RDA and the loss of their eldest son, Jake Sully and Neytiri face a new threat on Pandora: the Ash People, a violent and power-hungry Na''vi tribe led by the ruthless Varang. Jake''s family must fight for their survival and the future of Pandora in a conflict that pushes them to their emotional and physical limits.', '83533.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Vengeance', 1, 2026, 'Rodrigo Valdes', 'The brutal murder of the wife of “Toro,” a military hero in the special forces, turns him into a man with a single purpose: revenge. After a stroke of fate makes him a millionaire, Carlos transforms his fortune into an arsenal and, together with his closest soldiers, sets out to hunt down those responsible.', '1613798.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Malena', 4, 2000, 'Giuseppe Tornatore', '12-year-old Renato experiences three significant events on the same day: the beginning of the Second World War, getting a bike, and witnessing the arrival of the gorgeous Malèna. Through his eyes, we see the curse of beauty and loneliness of Malena, whose husband is presumed dead, and, through his soul, we see his love for her.', '10867.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Project Hail Mary', 8, 2026, 'Phil Lord', 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.', '687163.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Crucifix: Blood of the Exorcist', 5, 2025, 'Stephen Roach', 'A gruesome discovery in the grounds of their new home plunges a young couple into a maelstrom of spiritual possession, pagan rituals, Viking battles, and violent revenge.', '1352874.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Shelter', 1, 2026, 'Ric Roman Waugh', 'A man living in self-imposed exile on a remote island rescues a young girl from a violent storm, setting off a chain of events that forces him out of seclusion to protect her from enemies tied to his past.', '1290821.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Devil Wears Prada', 4, 2006, 'David Frankel', 'A young woman from the Midwest gets more than she bargained for when she moves to New York to become a writer and ends up as the assistant to the tyrannical, larger-than-life editor-in-chief of a major fashion magazine.', '350.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('GOAT', 6, 2026, 'Tyree Dillihay', 'A small goat with big dreams gets a once-in-a-lifetime shot to join the pros and play roarball, a high-intensity, co-ed, full-contact sport dominated by the fastest, fiercest animals in the world.', '1297842.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Crime 101', 9, 2026, 'Bart Layton', 'When an elusive thief whose high-stakes heists unfold along the iconic 101 freeway in Los Angeles eyes the score of a lifetime, with hopes of this being his final job, his path collides with a disillusioned insurance broker who is facing her own crossroads. Determined to crack the case, a relentless detective closes in on the operation, raising the stakes even higher.', '1171145.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Demon Slayer: Kimetsu no Yaiba Infinity Castle', 6, 2025, 'Haruo Sotozaki', 'The Demon Slayer Corps are drawn into the Infinity Castle, where Tanjiro, Nezuko, and the Hashira face terrifying Upper Rank demons in a desperate fight as the final battle against Muzan Kibutsuji begins.', '1311031.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Mortuary Assistant', 5, 2026, 'Jeremiah Kipp', 'Rebecca Owens, a recent mortuary science graduate takes a night shift job at River Fields Mortuary. Initially, the job seems straightforward — embalming bodies, completing paperwork, and keeping things tidy. But once Rebecca starts working the night shift, things take a dark turn.', '1470130.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Zootopia 2', 7, 2025, 'Jared Bush', 'After cracking the biggest case in Zootopia''s history, rookie cops Judy Hopps and Nick Wilde find themselves on the twisting trail of a great mystery when Gary De''Snake arrives and turns the animal metropolis upside down. To crack the case, Judy and Nick must go undercover to unexpected new parts of town, where their growing partnership is tested like never before.', '1084242.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Rise of the Conqueror', 1, 2026, 'Jacob Schwarz', 'In the 14th-century, as the Silk Road crumbles and rival factions tear the land apart, fearless warrior Timur emerges from exile. Stripped of everything, he fights to unite the fractured kingdoms, using strategy and sheer will to carve an empire from chaos. Undefeated in battle and widely regarded as one of history’s greatest military leaders and tacticians, not to mention one of its most brutal, Timur would found the Timurid Empire, which ruled over modern-day Afghanistan, Iran and Central Asia.', '1207162.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('¿Quieres ser mi novia?', 2, 2026, 'Ihtzi Hurtado', 'Javi and Lu''s relationship faces dangerous territory as old and new temptations emerge: a young woman reigniting Javi''s chemistry and a mature man pursuing Lu. Through humor, entanglements, and surprises, their love is tested.', '1601797.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Sniper: No Nation', 1, 2026, 'Trevor Calverley', 'Brandon Beckett and Agent Zero lead a rescue mission in Costa Verde when their friends are taken hostage.', '1641319.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Predator: Badlands', 1, 2025, 'Dan Trachtenberg', 'Cast out from his clan, a young Predator finds an unlikely ally in a damaged android and embarks on a treacherous journey in search of the ultimate adversary.', '1242898.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Devil Wears Prada 2', 2, 2026, 'David Frankel', 'Andy Sachs returns to Runway as Miranda Priestly navigates a new media landscape and Runway''s position within. The duo reconnect with former assistant Emily Charlton, now the head of a luxury brand that possesses funding which could ensure Runway''s survival.', '1314481.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Fixer', 4, 2017, 'Adrian Sitaru', 'Romanian-born Radu Patru is a trainee at a prestigious French news network. Serving as a translator and general problem solver, or "fixer," for the headlining journalists during his trial period, he''s looking to make his big break. He sees his opportunity when two underage Romanian prostitutes are repatriated from France, creating an international scandal. Taking advantage of his language skills and local connections, Radu is prepared to do whatever it takes to interview one of the young girls. But as he ventures into tricky moral ground, he must stop to ask himself if, as an aspiring journalist, he can live with the consequences of his actions, and if, as a father, he''s setting a good example for his son.', '412201.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('After Porn Ends 2', 10, 2017, 'Bryce Wagoner', 'After Porn Ends 2 picks up where its predecessor left off and not only turns back the clock to meet the oldest living stars in adult film''s history, but goes in depth with some of Its most current retirees and juxtaposes their experiences in a life after porn. Delving deeper into society''s ongoing stigmas of race, misogyny, and the reality of decreasing opportunities for these former VHS box cover stars. For some, their careers in adult entertainment is accepted proudly and without regret. In fact, it seems to have proven to be the pathway to their current happiness and inner peace. For others, however, a career in porn has proven to be a conduit to certain despair as they struggle to find a way to bury their past and emerge with a new career or calling.', '440249.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Shadow''s Edge', 1, 2025, 'Larry Yang', 'Macau Police brings the tracking expert police officer out of retirement to help catch a dangerous group of professional thieves.', '1419406.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Early Man', 2, 2018, 'Nick Park', 'Dug, along with his sidekick Hognob, unite a cavemen tribe to save their hidden valley from being spoiled and, all together as a team, to face the menace of a mysterious and mighty enemy, on the turf of an ancient and sacred sport.', '387592.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Balls Up', 2, 2026, 'Peter Farrelly', 'Two marketing executives go "balls out" and pitch a bold full‑coverage condom sponsorship with the World Cup. After their drunken celebration in Brazil sparks a global scandal, they must outrun furious fans, criminals, and power-hungry officials to salvage their careers and make it home alive.', '1084577.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Housemaid', 11, 2025, 'Paul Feig', 'Trying to escape her past, Millie Calloway accepts a job as a live-in housemaid for the wealthy Nina and Andrew Winchester. But what begins as a dream job quickly unravels into something far more dangerous—a sexy, seductive game of secrets, scandal, and power.', '1368166.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Lee Cronin''s The Mummy', 5, 2026, 'Lee Cronin', 'The young daughter of a journalist disappears into the desert without a trace—eight years later, the broken family is shocked when she is returned to them, as what should be a joyful reunion turns into a living nightmare.', '1304313.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Monster on a Plane', 5, 2024, 'Ezra Tsegaye', 'An exotic animal turns into a monster and becomes a deadly danger for all passengers.', '1270125.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Scream 7', 5, 2026, 'Kevin Williamson', 'When a new Ghostface killer emerges in the quiet town where Sidney Prescott has built a new life, her darkest fears are realized as her daughter becomes the next target. Determined to protect her family, Sidney must face the horrors of her past to put an end to the bloodshed once and for all.', '1159559.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Red Book Ritual: Gates of Hell', 5, 2025, 'Carlos Baena', 'Robbie embarks on a dangerous quest to contact his deceased girlfriend through a ritual that summons the dead. He heads to an abandoned house with a group of young people to perform the "Red Book Ritual." But during the summoning, supernatural forces awaken. Now they must face ancient horrors to survive.', '1499885.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Thrash', 5, 2026, 'Tommy Wirkola', 'When a Category 5 hurricane decimates a coastal town, the storm surge brings devastation, chaos, and something far more frightening onto shore: hungry sharks.', '1290417.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Love and Magnets', 4, 2004, 'Yves Pelletier', 'Back in Montréal after spending five years in Guatemala, Julie moves in with her elder sister, Jeanne, a chronic liar and woman of rather loose sexual morals... Disillusioned with love, Jeanne is nevertheless engaged to Noël. However, Jeanne and Noël lead separate lives, and only communicate by leaving each other messages on the fridge.Everything suddenly becomes very complicated. Jeanne compels Julie to take up with Noël so she can have a fling with a passionate musician. Noël, meanwhile, sets Julie up with Michel -- without Jeanne''s knowledge.  Julie mixes things up even further. Egged on by her friend Marie-Ève, she alters the contents of the messages on the fridge in an attempt to breathe new life into Jeanne and Noël''s relationship. Along the way, she also begins to fall for the seductive Michel. The tables are turned on everyone... In the game of love and truth, illusion leads to betrayal, but love conquers all.', '16423.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Brothers Under Fire', 1, 2026, 'Justin Chadwick', 'Captain Jordan Wright''s squadron on leave for a wedding in Mexico encounters a murderous cartel. As Jordan tries to lead survivors to safety, war erupts between his squad and the cartel, forcing him into a battle to save his men.', '1414413.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Kranti', 1, 2002, 'Naresh Malhotra', 'Inspector Abhay Pratap Singh is a young, honest and diligent police inspector, serving with Bombay Police, and comes from a respectable family, which consists of sister Anu; mom Sushma; and dad, Awadesh, who is also the Commissioner of Police. Abhay has long suspected Mahendra Pratap Rana of being a criminal don, who also has links with terrorists, but thus far has been unable to gather any material evidence for the police to lay charges. The Commissioner is unable to accept his son''s word, as Mahendra is well-known, influential, and wealthy. Abhay continues to pursue his investigation despite of warnings from his superiors, and is ultimately suspended from duty. Now even after suspension, Abhay has come to know that the life of Coloney Krishnakanth is threatened by Mahendra, and reaches out to his dad, who will not have anything to do with him anymore. It will upto Abhay to save the life of Krishnakanth, against all odds that are stacked up against him.', '545339.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Interstellar', 7, 2014, 'Christopher Nolan', 'The adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.', '157336.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Enforcer', 1, 2022, 'Richard Hughes', 'A noir thriller set in Miami, the film follows an enforcer who discovers his femme fatale boss has branched out into cyber sex trafficking, putting a young runaway he’s befriended at risk. He sacrifices everything to save the young girl from the deadly organization he’s spent his life building.', '846433.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Night Nurse', 2, 1979, 'Mariano Laurenti', 'A dentist invites a elderly patient to stay at his home to recover, unaware that he is a jewel thief. He plans to steal a valuable diamond but then runs into a beautiful nurse who, aside from constantly stripping nude, has plans of her own.', '58008.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('War of the Worlds', 8, 2025, 'Rich Lee', 'Will Radford is a top analyst for Homeland Security who tracks potential threats through a mass surveillance program, until one day an attack by an unknown entity leads him to question whether the government is hiding something from him... and from the rest of the world.', '755898.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Strangers: Chapter 3', 5, 2026, 'Renny Harlin', 'Tethered by a frightening conclusion, Maya and the Strangers are locked on an unavoidable, unforgiving collision course — a showdown that proves they’re far from strangers now.', '1010755.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Captain Kate', 4, 1911, 'Francis Boggs', 'Two caravans meet on the desert, one headed by Howell and Clancy, two New York men, who are gathering animals for circus purposes, the other is led by an old animal tamer named Desmond and his beautiful daughter, whom the natives have nicknamed Capt. Kate. After exchanging cards, the caravans go their separate ways. Desmond is stricken and dies, leaving Kate alone. She assumes her father''s perilous business, leading her party of native hunters after big game. Later, one of the hunters is stricken and the superstitious followers of Capt. Kate, recognizing the nature of the disease, abandon the hunt and their leader, one servant alone remaining faithful to his mistress. Kate, realizing that she can go no further without assistance, calls a halt and they erect a crude hut in which she is to live, while the servant goes in search of Clancy. Scene of Kate''s isolated life and her dangers follow. She is besieged by wild animals, who make her life a long nightmare of peril.', '419858.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('The Super Mario Bros. Movie', 2, 2023, 'Aaron Horvath', 'While working underground to fix a water main, Brooklyn plumbers—and brothers—Mario and Luigi are transported down a mysterious pipe and wander into a magical new world. But when the brothers are separated, Mario embarks on an epic quest to find Luigi.', '502356.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Man in the Mirror: The Michael Jackson Story', 4, 2004, 'Allan Moyle', 'Chronicles the rise and fall of pop king Michael Jackson.', '73353.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('xXx', 1, 2002, 'Rob Cohen', 'Xander Cage is your standard adrenaline junkie with no fear and a lousy attitude. When the US Government "recruits" him to go on a mission, he''s not exactly thrilled. His mission: to gather information on an organization that may just be planning the destruction of the world, led by the nihilistic Yorgi.', '7451.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Bodycam', 5, 2026, 'Brandon Christensen', 'A call to a quiet suburban home unleashes unthinkable carnage when two officers mistakenly shoot a man and his infant child, spiraling the tragedy into a fierce, unrelenting fall into the unknown.', '1510745.jpg');
INSERT INTO movies (title, genre_id, year, director, synopsis, poster_filename) VALUES ('Tu Yaa Main', 11, 2026, 'Bejoy Nambiar', 'A wannabe rapper from the outskirts of Mumbai and an affluent influencer elope to a coastal town, only to find themselves trapped in the pool of a derelict resort fighting for survival against the wrath of a ferocious crocodile.', '1446616.jpg');
